declare(strict_types=1);
function renewalRuntimeDigest(): string
{
    $root=dirname(__DIR__,2).'/Domains';$files=[];
    foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS)) as $file){
        if($file->isFile()&&$file->getExtension()==='php'){$files[substr($file->getPathname(),strlen($root)+1)]=hash_file('sha256',$file->getPathname());}
    }
    ksort($files);return hash('sha256',json_encode($files,JSON_THROW_ON_ERROR));
}
/** Restore only an authentic, source-bound empty installation, never an activation assembled by a fixture. */
function initializedRenewalFixture(): void
{
    $snapshot=json_decode(file_get_contents(__DIR__.'/../fixtures/renewal-initialized.json'),true,512,JSON_THROW_ON_ERROR);
    same(renewalRuntimeDigest(),$snapshot['runtime_sha256'],'Renewal setup must be regenerated through the real installer for this source');
    same(DOMAINS_TEST_NATIVE_COMMIT,$snapshot['paymenter_commit'],'Prepared setup uses the native source pin');
    same('sqlite',Illuminate\Support\Facades\DB::connection()->getDriverName(),'Prepared renewal setup is SQLite only');
    same([],array_values(array_filter(Illuminate\Support\Facades\Schema::getTableListing(),static fn($t)=>str_starts_with($t,'domains_'))),'Prepared renewal setup requires an empty module');
    $pdo=Illuminate\Support\Facades\DB::connection()->getPdo();
    Illuminate\Support\Facades\DB::transaction(static function()use($pdo,$snapshot):void{
        foreach($snapshot['schema'] as $sql){$pdo->exec($sql);}
        foreach($snapshot['rows'] as $table=>$rows){
            foreach($rows as $row){$columns=array_keys($row);$query=$pdo->prepare('INSERT INTO "'.$table.'" ("'.implode('","',$columns).'") VALUES ('.implode(',',array_fill(0,count($columns),'?')).')');$query->execute(array_values($row));}
        }
    });
    Paymenter\Extensions\Servers\Domains\Services\Runtime::register();
    (new Paymenter\Extensions\Servers\Domains\Services\Installation)->verify();
    same('active',Paymenter\Extensions\Servers\Domains\Catalogue\UpgradeGate::routeState()['state'],'Restored setup retains authentic initialization');
    same([],Illuminate\Support\Facades\DB::select('PRAGMA foreign_key_check'),'Prepared setup preserves native foreign keys');
}
